    float correctTemperature = temperature - 5;
    float correctHumidity = humidity - 10;

    Serial.print("Corrected Temperature = ");
    Serial.print(correctTemperature);
    Serial.println(" *C");
    Serial.print("Corrected Humidity = ");
    Serial.print(correctHumidity);
    Serial.println(" %");
  }

  // Wait 10 seconds before taking the next reading
